/* Test-only native activation diagnostics. The product adapter has read access
   only. Here we restore a native fight checkpoint and log gauge/position writes
   to exercise motion admission; these are not claimed as input-only replays. */
window.NativeShortcutDiagnostic=(()=>{
 const a=SSF2TNative,grid=[[0,1,2,3,13,14,10,9],[4,5,6,7,12,15,11,8]],oldCodes=[[1,1,1,2],[8,8,8,4],[1,2,2,2],[8,4,4,4],[2,2,2,1],[4,4,4,8],[2,1,1,1],[4,8,8,8],[4,8,8,4],[8,4,4,8],[1,2,2,1],[2,1,1,2],[8,8,4,4],[1,1,2,2],[2,2,1,1],[4,4,8,8]];
 let checkpoint=null,ram=null,subject=0,config=null,prefix=[],effective=[],recording=false;
 const nativeTick=__nativeTestModule._ssf_tick;__nativeTestModule._ssf_tick=(p,q)=>{if(recording)effective.push([p,q]);return nativeTick(p,q);};
 const tape=()=>{const r=[];for(const[k,j]of effective){if(r.length&&r.at(-1)[0]===k&&r.at(-1)[1]===j)r.at(-1)[2]++;else r.push([k,j,1]);}return r;};
 const run=(n,k=0,j=0)=>a.advance(n,k,j,false),press=(slot,key,n=3)=>{run(n,slot?0:key,slot?key:0);run(9);},read32=address=>(a.read(address,2)*65536+a.read(address+2,2))>>>0;
 function findRAM(){const heap=__nativeTestModule.HEAPU8,at=0xff844e,len=256,matches=[];for(const swap of[0,1]){const sig=Uint8Array.from({length:len},(_,i)=>a.read((at+i)^swap,1)),pivots=Array.from(sig.entries()).filter(([i,v])=>v).slice(0,20),[pivot,value]=pivots[0];let pos=heap.indexOf(value);while(pos>=0){const start=pos-pivot,base=start-(at&65535);if(base>=0&&base+65536<=heap.length&&pivots.every(([i,v])=>heap[start+i]===v)&&sig.every((v,i)=>heap[start+i]===v))matches.push({base,swap});pos=heap.indexOf(value,pos+1);}}if(matches.length!==1)throw Error('Expected unique diagnostic RAM mapping: '+matches.length);const q=matches[0];for(let i=0;i<1000;i++){const address=0xff0000+(i*67&65535);if(a.read(address,1)!==heap[q.base+((address&65535)^q.swap)])throw Error('RAM map verification');}return q;}
 function write8(address,value,log){if(![0xff8702,0xff8b02,0xff8454,0xff8455,0xff8854,0xff8855].includes(address))throw Error('Unapproved diagnostic write');__nativeTestModule.HEAPU8[ram.base+((address&65535)^ram.swap)]=value;log.push({beforeFrame:a.state().frame+1,address,size:1,value});}
 function write16(address,value,log){write8(address,value>>8,log);write8(address+1,value&255,log);}
 function select(slot,id){const current=a.read(slot?0xff8bdf:0xff87df,1);let from,to;for(let y=0;y<2;y++)for(let x=0;x<8;x++){if(grid[y][x]===current)from=[x,y];if(grid[y][x]===id)to=[x,y];}if(from[1]!==to[1])press(slot,to[1]?4:8);for(let x=from[0];x!==to[0];x+=to[0]>from[0]?1:-1)press(slot,to[0]>from[0]?1:2);}
 function setup(id,slot=0,old=false){subject=slot;a.setShortcuts(false);a.reset();effective=[];recording=true;run(3001);run(30,2048,2048);run(30);run(30,2048,2048);run(60);run(12,1024,1024);run(238);
  if(id===16){select(slot,0);run(65);for(const q of[13,3,12,0]){select(slot,q);run(65);}run(3,slot?0:1024,slot?1024:0);run(1);run(3,slot?0:112,slot?112:0);run(3);}
  else{select(slot,id);if(old){run(3,slot?0:16,slot?16:0);run(3);for(const d of oldCodes[id]){run(3,slot?0:d,slot?d:0);run(3);}run(3,slot?0:80,slot?80:0);run(3);}else press(slot,16,12);}
  press(1-slot,16,12);for(let i=0;i<2000&&!(a.state().gameStep===4&&a.state().matchStep===10);i++)run(1);run(10);const state=a.state(),p=state.players[slot];if(state.playersIn!==3||p.id!==(id===16?0:id)||p.akuma!==(id===16)||p.old!==old)throw Error('Wrong diagnostic match '+JSON.stringify({id,slot,old,state}));ram=findRAM();checkpoint=__nativeTestModule.HEAPU8.slice();prefix=effective.slice();recording=false;config={id,slot,old};return{config,state,ramMapVerified:true,moves:a.aiShortcutMoves()[slot]};
 }
 function test(pair,{reverse=false,filled=true,frames=200,followAt=null}={}){
  if(__nativeTestModule.HEAPU8.length!==checkpoint.length)throw Error('Diagnostic heap grew');__nativeTestModule.HEAPU8.set(checkpoint);a.setShortcuts(false);effective=prefix.slice();recording=true;const base=0xff844e+subject*0x400,other=base+(subject?-0x400:0x400),writes=[],start=a.state(),m=a.aiShortcutMoves()[subject].find(q=>q.pair===pair);if(!m)throw Error('Unavailable test command');
  if(reverse){write16(0xff8454,start.players[1].x,writes);write16(0xff8854,start.players[0].x,writes);}
  if(m.grab){const p=a.state().players,center=(p[0].x+p[1].x)/2,left=p[subject].x<p[1-subject].x;write16(base+6,Math.round(center+(left?-12:12)),writes);write16(other+6,Math.round(center+(left?12:-12)),writes);}
  run(4);if(m.super&&filled)write8(base+0x2b4,48,writes);a.setShortcuts(true);run(2);let special=null,normal=null,lift=0,down=false,spent=false,first=null,peak=40,lo=Infinity,hi=-Infinity;const native=[];
  try{for(let t=0;t<frames;t++){run(1,subject?0:t===0||t===followAt?m.chord:0,subject?t===0||t===followAt?m.chord:0:0);const s=a.state(),p=s.players[subject],o=s.players[1-subject],selector=a.read(base+0x8b,1);if(t===0)first=a.aiShortcuts().players[subject];if(p.state===12&&!special)special={t,selector,step:a.read(base+4,1),frame:read32(base+0x1a)};if(p.state===10&&!normal)normal={t,selector,at80:a.read(base+0x80,1),frame:read32(base+0x1a)};lift=Math.max(lift,o.y-40);down||=o.state===20;peak=Math.max(peak,p.y);spent||=m.super&&filled&&a.read(base+0x2b4,1)<48;lo=Math.min(lo,p.x);hi=Math.max(hi,p.x);if(config.id===3&&pair===1&&t>=82&&t<105)native.push({t,state:p.state,output:a.aiShortcuts().players[subject].output,input392:a.read(base+0x392),charge86:a.read(base+0x86,1),count87:a.read(base+0x87,1),window88:a.read(base+0x88,1),input3a6:a.read(base+0x3a6)});if(s.error)throw Error(s.error);}}
  catch(error){recording=false;return{...config,pair,name:m.name,reverse,error:error.message,first,special,normal,writes,inputRLE:tape()};}
  recording=false;return{...config,pair,name:m.name,reverse,inputRLE:tape(),first,special,normal,native,lift,down,peak,travel:hi-lo,spent,gauge:a.read(base+0x2b4,1),last:a.aiShortcuts().players[subject],hp:a.state().players.map(p=>p.hp),writes};
 }
 function raw(seq,{filled=false,near=false,speed=null}={}){__nativeTestModule.HEAPU8.set(checkpoint);a.setShortcuts(false);const b=0xff844e+subject*0x400,log=[];if(near){const ps=a.state().players,c=(ps[0].x+ps[1].x)/2;write16(b+6,Math.round(c-12),log);write16((subject?0xff844e:0xff884e)+6,Math.round(c+12),log);}run(4);if(speed!==null)a.setting(1,speed);if(filled)write8(b+0x2b4,48,log);let special=null,normal=null,peak=40,at=0;const ys=[];for(const[k,n]of seq)for(let i=0;i<n;i++){run(1,subject?0:k,subject?k:0);const p=a.state().players[subject],base=0xff844e+subject*0x400;if(p.state===12&&!special)special={at,frame:read32(base+0x1a),selector:a.read(base+0x8b,1)};if(p.state===10&&!normal)normal={at,frame:read32(base+0x1a)};peak=Math.max(peak,p.y);ys.push(p.y);at++;}return{special,normal,peak,ys,gauge:a.read(b+0x2b4,1),hp:a.state().players.map(p=>p.hp)};}return{setup,test,raw};
})();
